-- Generated by `python -m motherlode.ddl --write` from the field list in motherlode/prompts.py. Do not edit.
CREATE TABLE IF NOT EXISTS MOTHERLODE.CORE.DEALS (
    DOC_ID                     VARCHAR NOT NULL COMMENT 'The announcement this row was extracted from (DOCUMENTS.DOC_ID).',
    PROJECT_NAME               VARCHAR COMMENT 'The name of the acquired project(s).',
    PRIMARY_COMMODITY          VARCHAR COMMENT 'The main chemical symbol of the primary commodity (e.g., Au, Cu, Fe).',
    COMMODITIES                VARCHAR COMMENT 'A comma-separated list of other associated elements/metals.',
    RESOURCE_VALUE_SCRAPED     VARCHAR COMMENT 'The declared mineral resource statement (follow the critical rule below).',
    STAGE                      VARCHAR COMMENT 'Internal stage label (DO NOT POPULATE, leave for manual input).',
    STAGE_MINING_HUB           VARCHAR COMMENT 'The stage classification from Mining Hub, if the source is Mining Hub.',
    STAGE_SCRAPPED             VARCHAR COMMENT 'The project''s development level as described in the news (e.g., Exploration, Advanced Stage, Mining).',
    PROJECT_STATE_OR_PROVINCE  VARCHAR COMMENT 'The state or province where the project is located.',
    PROJECT_COUNTRY            VARCHAR COMMENT 'The country where the project is located.',
    LONGITUDE                  FLOAT COMMENT 'Geographic longitude in decimal degrees.',
    LATITUDE                   FLOAT COMMENT 'Geographic latitude in decimal degrees.',
    PROJECT_AREA               FLOAT COMMENT 'The project''s surface area.',
    PROJECT_AREA_UNIT          VARCHAR COMMENT 'The unit for the project area (e.g., ha, km2).',
    OWNER_NAME                 VARCHAR COMMENT 'The company buying the project (the BUYER).',
    OWNER_TICKER               VARCHAR COMMENT 'The stock ticker of the buying company.',
    OWNER_MARKETCAP            FLOAT COMMENT 'The market capitalization of the buying company.',
    NEWS_LINK                  VARCHAR COMMENT 'The URL of the scraped news article.',
    NEWS_TITLE                 VARCHAR COMMENT 'The title of the news article.',
    DEAL_TYPE                  VARCHAR COMMENT 'The type of deal announced (e.g., option agreement, earn-in agreement, JV, sale).',
    DEAL_PERIOD                VARCHAR COMMENT 'The duration of the deal (e.g., "4 years").',
    INTEREST_ACQUIRED_PERCENT  FLOAT COMMENT 'The percentage of interest acquired in the deal.',
    AGGREGATE_DEAL_CURRENCY    VARCHAR(3) COMMENT 'The currency of the aggregate deal value (3-letter ISO code).',
    AGGREGATE_DEAL_VALUE       FLOAT COMMENT 'The total sum of all payments in the deal.',
    CASH_PAYMENTS_CURRENCY     VARCHAR(3) COMMENT 'The currency of the cash payments (3-letter ISO code).',
    CASH_PAYMENTS_VALUE        FLOAT COMMENT 'The total sum of all cash payments.',
    EXP_COMIT_CURRENCY         VARCHAR(3) COMMENT 'The currency of exploration expenditure commitments (3-letter ISO code).',
    EXP_COMIT_VALUE            FLOAT COMMENT 'The total sum of exploration expenditure commitments.',
    DRILLING_AMOUNT            FLOAT COMMENT 'Total meters committed to be drilled.',
    DRILLING_VALUE             FLOAT COMMENT 'The estimated cost of drilling or the reported value.',
    SHARES_CURRENCY            VARCHAR(3) COMMENT 'The currency used to value the share payment (3-letter ISO code).',
    SHARES_VALUE               FLOAT COMMENT 'The equivalent value paid in shares.',
    SHARES_VALUE_SCRAPED       FLOAT COMMENT 'The equivalent value paid in shares if explicitly stated in the news.',
    SHARES_AMOUNT              FLOAT COMMENT 'The number of shares used in the payment.',
    SHARE_PRICE                FLOAT COMMENT 'The price per share used for the valuation.',
    NSR_PERCENT                FLOAT COMMENT 'The reported Net Smelter Royalty (NSR) or GRR as a percentage.',
    NEWS_DATE                  DATE COMMENT 'The date of the news article in YYYY-MM-DD format.',
    CONTINENT                  VARCHAR COMMENT 'Continent of the project, from AI_CLASSIFY.',
    DEAL_CATEGORY              VARCHAR COMMENT 'Deal type from a fixed list, from AI_CLASSIFY (deal_type is the model''s free text).',
    EXTRACTOR                  VARCHAR COMMENT 'Which function produced the row: AI_COMPLETE with a model name, or AI_EXTRACT.',
    ATTEMPTS                   NUMBER(2) COMMENT 'Extraction attempts used (2 means the corrected retry ran).',
    OUTCOME                    VARCHAR COMMENT 'stored, or stored_partial when unsupported values were withheld.',
    LOADED_AT                  TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'When the row was written.',
    CONSTRAINT DEALS_PK PRIMARY KEY (DOC_ID)
)
COMMENT = 'One row per project transaction, written only after every number was checked against the announcement.';
